import{_ as a,o as i,c as l,ag as t}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"UncivCN Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"UncivCN/Changelog.md","filePath":"UncivCN/Changelog.md"}'),o={name:"UncivCN/Changelog.md"};function r(n,e,s,d,u,c){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="uncivcn-changelog" tabindex="-1">UncivCN Changelog <a class="header-anchor" href="#uncivcn-changelog" aria-label="Permalink to &quot;UncivCN Changelog&quot;">​</a></h1><p>Version rule: upstream version + CN sub-version (<code>.1</code>, <code>.2</code>, <code>.3</code>…; the same upstream version can have multiple CN sub-versions, e.g. 4.20.8.1 → 4.20.8.4; restarts at <code>.1</code> after merging a new upstream, e.g. 4.21.5 → 4.21.5.1).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Upstream (vanilla) release notes: <a href="https://github.com/yairm210/Unciv/blob/master/changelog.md" target="_blank" rel="noreferrer">official Unciv changelog</a></p></div><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><h2 id="_4-21-10-5-build-1260" tabindex="-1">4.21.10.5 (build 1260) <a class="header-anchor" href="#_4-21-10-5-build-1260" aria-label="Permalink to &quot;4.21.10.5 (build 1260)&quot;">​</a></h2><ul><li><p>Multiplayer: simultaneous-turn submissions accept omitted default fields</p></li><li><p>Multiplayer: fixed clients incorrectly falling back after successful operation uploads</p></li><li><p>Multiplayer: added HTTP polling fallback when operation signals are missed</p></li><li><p>Fix: in-game update checks now verify CN download server synchronization</p></li><li><p>Multiplayer: simultaneous turns now advance after all players submit</p></li><li><p>Multiplayer: simultaneous-turn submissions now use the dedicated atomic operation store</p></li></ul><h2 id="_4-21-10-3-build-1258" tabindex="-1">4.21.10.3 (build 1258) <a class="header-anchor" href="#_4-21-10-3-build-1258" aria-label="Permalink to &quot;4.21.10.3 (build 1258)&quot;">​</a></h2><ul><li>Multiplayer: added the experimental simultaneous-turn operation protocol</li><li>Multiplayer: simultaneous-turn operation files are deduplicated by player and sequence</li><li>Multiplayer: simultaneous turns now replay unit orders without rerolling combat</li><li>Multiplayer: fortify, sleep and skip orders are included in simultaneous turns</li><li>Multiplayer: simultaneous-turn settlement now uses an atomic server lock</li><li>Multiplayer: expanded simultaneous-turn snapshots to diplomacy popups, events and special unit UI</li><li>Multiplayer: automated, Lua and triggered unit effects are replayed from result snapshots</li><li>Multiplayer: simultaneous turns now record city production, technology and policy choices</li><li>Multiplayer: complex unit actions now replay modded state changes</li><li>Modding: unit-scope variables - attach integer counters to individual units (see <a href="/Unciv/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#variables-json">Variables.json</a>)</li><li>Modding: unit experience is now a variable, old saves migrate automatically (see <a href="/Unciv/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#variables-json">Variables.json</a>)</li><li>Modding: variables support city, civilization and global scopes (see <a href="/Unciv/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#variables-json">Variables.json</a>)</li><li>Modding: variables support bounds, per-turn yields, percentage bonuses, purchase costs, production conversion (see <a href="/Unciv/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#variables-json">Variables.json</a>)</li><li>Modding: variables support Lua read/write and scope-aware UI (see <a href="/Unciv/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#variables-json">Variables.json</a>)</li><li>Modding: civilization-scope variables now need an explicit scope declaration</li><li>Fix: variable purchases charge exact cost, values survive reloads, no AI crashes</li><li>Modding: variables work in all countable positions and Set triggerables (see <a href="/Unciv/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#variables-json">Variables.json</a>)</li><li>Merged upstream: fixed repair with only a pillaged road left, and an ANR when opening the Civilopedia</li><li>Merged upstream: CN features adapted to the new architecture, behavior unchanged</li><li>Docs: CoeHarMod changelog moved to the mods section (see <a href="/Unciv/Community/Mods/CoeHarMod/changelog/">changelog</a>)</li><li>Docs: upstream changelog replaced by a link at the top of this page</li><li>Docs: changelog entries limited to 30 words; big changes may be split into multiple entries</li></ul><h2 id="_4-21-10-2-build-1257" tabindex="-1">4.21.10.2 (build 1257) <a class="header-anchor" href="#_4-21-10-2-build-1257" aria-label="Permalink to &quot;4.21.10.2 (build 1257)&quot;">​</a></h2><ul><li>Update: updates are now routed by region - mainland China uses the official CN server (see <a href="https://github.com/blyrin/unciv-srv/blob/main/README.md" target="_blank" rel="noreferrer">server-ts/README.md</a>)</li><li>Update: first launch asks your region (changeable in Options - Advanced)</li><li>Merged upstream: fixed several spectator and city-screen crashes</li></ul><h2 id="_4-21-10-1-build-1256" tabindex="-1">4.21.10.1 (build 1256) <a class="header-anchor" href="#_4-21-10-1-build-1256" aria-label="Permalink to &quot;4.21.10.1 (build 1256)&quot;">​</a></h2><ul><li>Modding: new civilization-scope variables with conditionals, triggers and Lua (see <a href="/Unciv/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#variables-json">Variables.json</a>)</li><li>Modding: variable display (top bar, resources overview) is configurable (see <a href="/Unciv/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#variables-json">Variables.json</a>)</li><li>Modding: conditional amounts (e.g. <code>when above [amount] ...</code>, HP/movement/population thresholds) now accept Countable expressions like <code>[Cities]</code> - see <a href="/Unciv/Modders/Unique-parameters.html#countable">Unique parameters</a></li><li>Merged upstream: UI and crash fixes, squashed promotion notifications</li><li>Fix: rotational-symmetry map generation glitches (wrapped/mirror maps) (see <a href="/Unciv/UncivCN/Features.html">Features</a>)</li></ul><h2 id="_4-21-8-3-build-1255" tabindex="-1">4.21.8.3 (build 1255) <a class="header-anchor" href="#_4-21-8-3-build-1255" aria-label="Permalink to &quot;4.21.8.3 (build 1255)&quot;">​</a></h2><ul><li>Multiplayer: new &quot;Forbid reloading&quot; option - no redoing turns by re-entering</li><li>Modding: new immediate production overflow unique (see <a href="/Unciv/Modders/uniques.html">uniques</a>)</li></ul><h2 id="_4-21-8-2-build-1254" tabindex="-1">4.21.8.2 (build 1254) <a class="header-anchor" href="#_4-21-8-2-build-1254" aria-label="Permalink to &quot;4.21.8.2 (build 1254)&quot;">​</a></h2><ul><li>Fix: map pin (tile note) previews no longer render unrevealed resources ahead of time (e.g. no oil in the Ancient era)</li><li>Modding: Civ6-style unit maintenance (opt-in), upkeep shown in Civilopedia (see <a href="/Unciv/Modders/Mod-file-structure/4-Unit-related-JSON-files.html">Units.json</a> and <a href="/Unciv/Modders/uniques.html">uniques</a>)</li><li>Modding: [amount]-type parameters now fully support Countable expressions (radii, amounts, free units, heal/damage/XP values, turn conditions) - see <a href="/Unciv/Modders/Unique-parameters.html">Unique parameters</a></li><li>Modding: new trigger, conditional and reverse uniques (combat / pillage / raze triggers, fortified / embarked conditionals, lose control over tiles / lose a spy / end a golden age / hide explored tiles) - see <a href="/Unciv/Modders/uniques.html">uniques</a></li><li>Modding/Lua: Lua can modify tile yields, take over combat strength and damage formulas, and react to combat / capture events with full attacker-defender context - see <a href="/Unciv/Modders/Lua-Modding.html">Lua Modding</a></li><li>Modding: new ModOptions.json version fields (<code>recommendedGameVersion</code>, <code>recommendedVersion</code> dependencies) with a non-blocking warning when the game version differs - see <a href="/Unciv/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html">ModOptions.json</a></li><li>Modding: merge (REMOVE_FIELD) crash on float fields fixed - see <a href="/Unciv/Modders/Mod-file-structure/6-MergeActions.html">MergeActions</a></li></ul><h2 id="_4-21-8-1-build-1253" tabindex="-1">4.21.8.1 (build 1253) <a class="header-anchor" href="#_4-21-8-1-build-1253" aria-label="Permalink to &quot;4.21.8.1 (build 1253)&quot;">​</a></h2><ul><li>Merged upstream: crash fixes, new optional &quot;Tiles Explored&quot; ranking</li><li>Difficulty: AI unhappiness modifier for King and above is now 100/90/85/75 (was 90/85/75/60)</li><li>Modding: unit max HP is now moddable - <code>maxHP</code> field plus the new &quot;[relativeAmount] Max HP&quot; unique; wounded penalty scales with HP percentage - see <a href="/Unciv/Modders/Mod-file-structure/4-Unit-related-JSON-files.html">Units.json</a></li><li>Main menu bottom-right buttons: Discord entry replaced by a QQ group link, Baidu Tieba button added, GitHub button points to the CN fork; About page links updated</li><li>Docs site links adapt to the client language (Chinese clients get the /zh/ section)</li><li>In-game wiki links point to the CN docs site</li><li>Code cleanup &amp; bugfixes from a full-project review (dead code removed, city/filter bugs fixed)</li></ul><h2 id="_4-21-7-2-build-1252" tabindex="-1">4.21.7.2 (build 1252) <a class="header-anchor" href="#_4-21-7-2-build-1252" aria-label="Permalink to &quot;4.21.7.2 (build 1252)&quot;">​</a></h2><ul><li>Android: update popup downloads the APK in-game with progress and installs it (unknown-sources permission guided)</li><li>Android: downloads are interruption-safe, Install/Redownload buttons, copy to the public Downloads folder, old packages cleaned up</li><li>Main menu &quot;Download latest version&quot; lists the platform&#39;s installers and downloads the chosen one directly</li></ul><h2 id="_4-21-7-1-build-1251" tabindex="-1">4.21.7.1 (build 1251) <a class="header-anchor" href="#_4-21-7-1-build-1251" aria-label="Permalink to &quot;4.21.7.1 (build 1251)&quot;">​</a></h2><ul><li>Merged upstream 4.21.7 / 4.21.7-patch1 / patch2 (41 commits): AI war-logic fixes, Stealth Bomber Evasion, MP average turn times, minimap ANR fix, Gradle 9.4.1 + LibGDX 1.14.2</li><li>Lua API: added unit.getEraNumber() and civ.discoverTech() - see <a href="/Unciv/Modders/Lua-API-Reference.html">Lua API Reference</a></li><li>Mods: CoeHarMod moved to its own repo as a git submodule, rules consolidated via Lua</li></ul><h2 id="_4-21-6-6-build-1250" tabindex="-1">4.21.6.6 (build 1250) <a class="header-anchor" href="#_4-21-6-6-build-1250" aria-label="Permalink to &quot;4.21.6.6 (build 1250)&quot;">​</a></h2><ul><li>Automatic update check on the main menu (mirror fallback); &quot;Mod download source&quot; renamed &quot;Download source&quot;</li><li>Fixed Lua runtime crash on function-call arguments in custom API functions</li><li>Lua API expansion (~100 new methods), ConditionalLuaCheck unique, TriggerUponTradeMade hook - see <a href="/Unciv/Modders/Lua-Modding.html">Lua Modding</a></li><li>Lua map scripts: mods can ship a map generator (<code>scripts/</code>), new &quot;Lua Generated&quot; map type</li><li>Lua sandbox hardening; mod checker covers map-script APIs</li></ul><h2 id="_4-21-6-5-build-1249" tabindex="-1">4.21.6.5 (build 1249) <a class="header-anchor" href="#_4-21-6-5-build-1249" aria-label="Permalink to &quot;4.21.6.5 (build 1249)&quot;">​</a></h2><ul><li>Lua runtime errors now show line numbers; sandbox escape via package.loaded closed; instruction budget against runaway loops</li><li>New: multiplayer restart votes (host enables, everyone votes, timeout = agree, auto-restart)</li></ul><h2 id="_4-21-6-4-build-1248" tabindex="-1">4.21.6.4 (build 1248) <a class="header-anchor" href="#_4-21-6-4-build-1248" aria-label="Permalink to &quot;4.21.6.4 (build 1248)&quot;">​</a></h2><ul><li>New: &quot;Mod download source&quot; setting with China mirror support</li><li>New-game screen: save/load setups to named slots; clipboard buttons moved; &quot;Reset to defaults&quot; replaced by a built-in &quot;Default setup&quot;</li></ul><h2 id="_4-21-6-3-build-1247" tabindex="-1">4.21.6.3 (build 1247) <a class="header-anchor" href="#_4-21-6-3-build-1247" aria-label="Permalink to &quot;4.21.6.3 (build 1247)&quot;">​</a></h2><ul><li>Fixed Docker build copying stale Unciv.jar name; fixed MSI missing from releases</li></ul><h2 id="_4-21-6-2-build-1246" tabindex="-1">4.21.6.2 (build 1246) <a class="header-anchor" href="#_4-21-6-2-build-1246" aria-label="Permalink to &quot;4.21.6.2 (build 1246)&quot;">​</a></h2><ul><li>Fixed 47 missing + 10 empty Simplified Chinese translations for CN-specific UI strings</li></ul><h2 id="_4-21-6-1-build-1245" tabindex="-1">4.21.6.1 (build 1245) <a class="header-anchor" href="#_4-21-6-1-build-1245" aria-label="Permalink to &quot;4.21.6.1 (build 1245)&quot;">​</a></h2><ul><li>Notes keyed by gameId (no more leaking across saves)</li><li>Map/unit pins: long-press / Alt+click editing, note bubbles, crash fix, CN translations</li><li>Fixed duplicate size rows on the new-game screen; aligned bundled rulesets with upstream</li><li>Merged upstream 4.21.6 (CPU perf, AI worker adjacency, MP upload indicator)</li></ul><h2 id="_4-21-5-3-build-1244" tabindex="-1">4.21.5.3 (build 1244) <a class="header-anchor" href="#_4-21-5-3-build-1244" aria-label="Permalink to &quot;4.21.5.3 (build 1244)&quot;">​</a></h2><ul><li>Fixed CI test failures (translation template spaces, test mods tracked in repo); deployment notifications cleaned up</li></ul><h2 id="_4-21-5-2-build-1243" tabindex="-1">4.21.5.2 (build 1243) <a class="header-anchor" href="#_4-21-5-2-build-1243" aria-label="Permalink to &quot;4.21.5.2 (build 1243)&quot;">​</a></h2><ul><li>Official VitePress docs site (Chinese full-text search, EN/CN switch)</li><li>Unique documentation descriptions now available in Chinese</li><li>Local APK signing, UncivCN artifact names</li></ul><h2 id="_4-21-5-1-build-1242" tabindex="-1">4.21.5.1 (build 1242) <a class="header-anchor" href="#_4-21-5-1-build-1242" aria-label="Permalink to &quot;4.21.5.1 (build 1242)&quot;">​</a></h2><ul><li>Merged upstream 4.21.5 (AI war-logic fixes, CPU perf)</li><li>Unbundled the UCCC mod; new: export/import game setup to clipboard; citizen auto-lock tweaks; stats-display bug fixed</li></ul><h2 id="_4-21-0-2-2026-08-01" tabindex="-1">4.21.0.2 (2026-08-01) <a class="header-anchor" href="#_4-21-0-2-2026-08-01" aria-label="Permalink to &quot;4.21.0.2 (2026-08-01)&quot;">​</a></h2><ul><li>Fixed UCCC mod bugs</li></ul><h2 id="_4-21-0-1-2026-08-01" tabindex="-1">4.21.0.1 (2026-08-01) <a class="header-anchor" href="#_4-21-0-1-2026-08-01" aria-label="Permalink to &quot;4.21.0.1 (2026-08-01)&quot;">​</a></h2><ul><li>Synced recent upstream (mirror maps, stats panel); completed Chinese localization</li><li>Default MP server <code>sp.unciv.cn:30123</code>; citizen auto-lock button; bundled UCCC mod</li><li>RNG re-roll on load disabled in multiplayer</li></ul><h2 id="_4-20-17-2-2026-07-12" tabindex="-1">4.20.17.2 (2026-07-12) <a class="header-anchor" href="#_4-20-17-2-2026-07-12" aria-label="Permalink to &quot;4.20.17.2 (2026-07-12)&quot;">​</a></h2><ul><li>New: unit/map pins; radius parity restriction lifted; save version isolation; no more starvation when training settlers</li></ul><h2 id="_4-20-17-1-2026-07-04" tabindex="-1">4.20.17.1 (2026-07-04) <a class="header-anchor" href="#_4-20-17-1-2026-07-04" aria-label="Permalink to &quot;4.20.17.1 (2026-07-04)&quot;">​</a></h2><ul><li>Followed a month of upstream updates</li></ul><h2 id="_4-20-8-4-2026-05-26" tabindex="-1">4.20.8.4 (2026-05-26) <a class="header-anchor" href="#_4-20-8-4-2026-05-26" aria-label="Permalink to &quot;4.20.8.4 (2026-05-26)&quot;">​</a></h2><ul><li>Mod checker lints Lua errors; polling MP shows online status</li></ul><h2 id="_4-20-8-3-2026-05-23" tabindex="-1">4.20.8.3 (2026-05-23) <a class="header-anchor" href="#_4-20-8-3-2026-05-23" aria-label="Permalink to &quot;4.20.8.3 (2026-05-23)&quot;">​</a></h2><ul><li>Lua system enhanced; events hookable with Lua</li></ul><h2 id="_4-20-8-2-2026-05-22" tabindex="-1">4.20.8.2 (2026-05-22) <a class="header-anchor" href="#_4-20-8-2-2026-05-22" aria-label="Permalink to &quot;4.20.8.2 (2026-05-22)&quot;">​</a></h2><ul><li>Mods support <a href="/Unciv/Modders/Lua-Modding.html">Lua scripting</a></li><li>Fixed G&amp;K &quot;Elite Education&quot; not granting great people; TRY_INJECT cost bug</li><li>Amount parameters accept Countables</li></ul><h2 id="_4-20-8-1-2026-05-21" tabindex="-1">4.20.8.1 (2026-05-21) <a class="header-anchor" href="#_4-20-8-1-2026-05-21" aria-label="Permalink to &quot;4.20.8.1 (2026-05-21)&quot;">​</a></h2><ul><li>New: <a href="./Polling-multiplayer.html">polling multiplayer</a></li></ul><h2 id="_4-20-7-4-2026-05-19" tabindex="-1">4.20.7.4 (2026-05-19) <a class="header-anchor" href="#_4-20-7-4-2026-05-19" aria-label="Permalink to &quot;4.20.7.4 (2026-05-19)&quot;">​</a></h2><ul><li>Center-symmetric maps distribute resources symmetrically</li></ul><h2 id="_4-20-7-3-2026-05-19" tabindex="-1">4.20.7.3 (2026-05-19) <a class="header-anchor" href="#_4-20-7-3-2026-05-19" aria-label="Permalink to &quot;4.20.7.3 (2026-05-19)&quot;">​</a></h2><ul><li>Extended mod JSON system, see <a href="/Unciv/Modders/Mod-file-structure/6-MergeActions.html">MergeAction tutorial</a></li></ul><h2 id="_4-20-7-2" tabindex="-1">4.20.7.2 <a class="header-anchor" href="#_4-20-7-2" aria-label="Permalink to &quot;4.20.7.2&quot;">​</a></h2><p><strong>Released</strong>: 2026-05-19</p><ul><li>Android builds no longer bundle CoeHarMod</li><li>New: three mirrored map modes (2/3/6-fold center symmetry)</li></ul><h2 id="_4-20-6-3" tabindex="-1">4.20.6.3 <a class="header-anchor" href="#_4-20-6-3" aria-label="Permalink to &quot;4.20.6.3&quot;">​</a></h2><p><strong>Released</strong>: 2026-05-17</p><ul><li>New mod uniques:</li></ul><table tabindex="0"><thead><tr><th>English text</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Hidden from city screen</code></td><td>No longer shown in the city panel</td></tr><tr><td><code>Can be built [amount] times in each city</code></td><td>Can be built [amount] times in a single city</td></tr></tbody></table><h2 id="_4-20-6-1" tabindex="-1">4.20.6.1 <a class="header-anchor" href="#_4-20-6-1" aria-label="Permalink to &quot;4.20.6.1&quot;">​</a></h2><p><strong>Released</strong>: 2026-05-16</p><ul><li>Synced two months of upstream updates</li><li>Random-result variability folded into a settings toggle</li></ul><h2 id="_4-19-16-2" tabindex="-1">4.19.16.2 <a class="header-anchor" href="#_4-19-16-2" aria-label="Permalink to &quot;4.19.16.2&quot;">​</a></h2><p><strong>Released</strong>: 2026-03-02</p><ul><li>Ancient-ruin results re-rollable by reloading a save</li></ul><h2 id="_4-19-16-1" tabindex="-1">4.19.16.1 <a class="header-anchor" href="#_4-19-16-1" aria-label="Permalink to &quot;4.19.16.1&quot;">​</a></h2><p><strong>Released</strong>: 2026-03-01</p><ul><li>City-state quest results re-rollable by reloading a save</li></ul><h2 id="_4-19-15-cn2" tabindex="-1">4.19.15-cn2 <a class="header-anchor" href="#_4-19-15-cn2" aria-label="Permalink to &quot;4.19.15-cn2&quot;">​</a></h2><p><strong>Released</strong>: 2026-02-28</p><ul><li>New area-attack mod uniques (multi-target, distance falloff, self/counter damage)</li><li>Stats panel CSV export</li></ul><h2 id="_4-19-15" tabindex="-1">4.19.15 <a class="header-anchor" href="#_4-19-15" aria-label="Permalink to &quot;4.19.15&quot;">​</a></h2><p><strong>Released</strong>: 2026-02-26</p><ul><li>Android bundles <a href="https://github.com/AutumnPizazz/CoeHarMod" target="_blank" rel="noreferrer">CoeHarMod</a></li><li>Adjacent cities can swap tiles (opt-in via ModOptions unique)</li></ul>',82)])])}const b=a(o,[["render",r]]);export{p as __pageData,b as default};
